SELECT count(*) FROM public.title title WHERE EXISTS (SELECT 1 FROM public.company_name cn, public.company_type ct, public.movie_companies mc, public.movie_info mi WHERE title.id = mc.movie_id AND mc.company_type_id = ct.id AND mc.company_id = cn.id AND mi.movie_id = title.id AND cn.country_code != '[pl]' AND ct.kind = 'production companies' AND (mi.info = 'Sweden' OR mi.info = 'Norway' OR mi.info = 'Germany' OR mi.info = 'Denmark' OR mi.info = 'Swedish' OR mi.info = 'Denish' OR mi.info = 'Norwegian' OR mi.info = 'German' OR mi.info = 'English') AND title.production_year >= 1950 AND title.production_year <= 2010);
